    COMPACT(1), REGULAR(2), LARGE(3);          // enums can carry data
    private final int rank;
    SpotSize(int rank) { this.rank = rank; }
    boolean fits(SpotSize required) { return this.rank >= required.rank; } // behaviour on the value
